<?php defined('_JEXEC') or die; $team=is_array($workspace['selectedTeam']??null)?$workspace['selectedTeam']:null; ?>
<div class="dh-page-heading"><div><p class="dh-eyebrow">PEOPLE BEHIND THE FIXTURE</p><h1><?= $team ? $escape($team['name']??'Team') : 'Teams' ?></h1><p class="dh-lead">Source-scoped identities. Retained matches. A clearer record.</p></div><?php if ($team): ?><a class="dh-button" href="<?= $escape($route(['section'=>'teams'])) ?>">← All teams</a><?php endif; ?></div>
<?php if ($team): ?>
  <section class="dh-panel"><div class="dh-panel-heading"><div><p class="dh-eyebrow">DESCRIPTIVE STATISTICS</p><h2>Recent retained form</h2></div><span class="dh-badge">From final results</span></div><?php if (!empty($team['form'])): ?><div class="dh-table-wrap" role="region" aria-label="Recent team form" tabindex="0"><table class="dh-table"><caption>Recent results supplied by this source dataset</caption><thead><tr><th scope="col">Date</th><th scope="col">Opponent</th><th scope="col">Result</th><th scope="col">Goals for / against</th><th scope="col">Match</th></tr></thead><tbody><?php foreach ($team['form'] as $form): ?><tr><td><?= $escape($date($form['date']??null)) ?></td><th scope="row"><?= $escape($form['opponent']??'Not supplied') ?></th><td><span class="dh-form-result dh-form-<?= $escape(strtolower($form['result']??'unknown')) ?>"><?= $escape($form['result']??'—') ?></span></td><td><?= $escape($form['goals_for']??'—') ?> / <?= $escape($form['goals_against']??'—') ?></td><td><a href="<?= $escape($route(['section'=>'matches','match_id'=>$form['match_id']??''])) ?>">Open match <span aria-hidden="true">↗</span></a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="dh-empty">No retained final results are available for this team. Scheduled matches do not establish form.</p><?php endif; ?></section>
  <section class="dh-panel"><div class="dh-panel-heading"><div><p class="dh-eyebrow">THE SOURCE RECORD</p><h2>Team matches</h2></div></div><?php $matchList((array)($team['matches']??[]),'Retained team matches'); ?></section>
  <?php if (!empty($team['unknowns'])): ?><aside class="dh-note"><div><h2>What is not supplied</h2><ul><?php foreach ($team['unknowns'] as $unknown): ?><li><?= $escape($unknown) ?></li><?php endforeach; ?></ul></div></aside><?php endif; ?><details class="dh-panel dh-technical"><summary>Source-scoped team identifier</summary><code><?= $escape($team['id']??'') ?></code><p>Names from separate provider datasets are not silently merged.</p></details>
<?php else: ?>
  <?php $teams=$items($workspace['teams']??[]); if (!$teams): ?><section class="dh-panel"><p class="dh-empty">No teams are available in the retained data.</p></section><?php else: ?><div class="dh-entity-grid"><?php foreach ($teams as $row): ?><a class="dh-entity-card" href="<?= $escape($route(['section'=>'teams','team_id'=>$row['id']??''])) ?>"><span class="dh-team-mark" aria-hidden="true"><?= $escape(mb_substr($row['name']??'?',0,1)) ?></span><span><strong><?= $escape($row['name']??'Unknown team') ?></strong><small><?= $escape($row['competition']??'Competition not supplied') ?></small></span><span class="dh-arrow" aria-hidden="true">↗</span></a><?php endforeach; ?></div><?php endif; ?>
<?php endif; ?>
